// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Each code point includes lone surrogates. Each block starts with FNV offset 2166136261.
// Feed one UTF-16 '0'/'1' unit per result, in u, v order for each code point.
const pattern0 = /^\p{General_Category=Letter}$/u;
const pattern1 = /^\p{General_Category=Letter}$/v;
const expected: number[] = [
  0xb2ec9757, 0xcaf3a7ed, 0x63eedbb3, 0xcf60588f, 0x2a7c1545, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5,
  0x956d3dc5, 0x956d3dc5, 0xdd6217cb, 0x956d3dc5, 0x956d3dc5, 0x5f90bf9d, 0xfa431dc5, 0x33040cf7,
  0xcc4f66cf, 0x9c9382d1, 0x9817fdfb, 0x9936d431, 0x164cfbf9, 0xfa431dc5, 0xb8cec10d, 0x956d3dc5,
  0x23ecbfcf, 0xfa431dc5, 0x5dd74a87, 0xddd00723, 0xfa431dc5, 0xd692b707, 0xd72fccc7, 0xfa431dc5,
  0x956d3dc5, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5, 0x956d3dc5,
  0x956d3dc5, 0x956d3dc5, 0xd8adc985, 0x2c5ce801, 0x60870a01, 0x956d3dc5, 0x3dfcbf9b, 0xb9af3041,
  0x956d3dc5, 0x156d3d13, 0x956d3dc5, 0xadd735f9, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
];
assert.sameValue(expected.length, 64);
for (let block = 0x000000; block < 0x040000; block += 4096) {
  let hash = 2166136261;
  for (let cp = block; cp < block + 4096; cp++) {
    const input = String.fromCodePoint(cp);
    hash = Math.imul(hash ^ (pattern0.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (pattern1.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
  }
  assert.sameValue(hash, expected[(block - 0x000000) / 4096], "General_Category=Letter block U+" + block.toString(16));
}
